const shelf = {
  books: ["Emma", "Dune"],
  count() {
    let found = 0;

    this.books.forEach(function () {
      if (this === undefined) {
        found += 1;
      }
    });

    return found;
  },
  reader() {
    return function () {
      return typeof this;
    };
  },
};

console.log(shelf.count());
console.log(shelf.reader()());
